@njit
def norm2(x):
    s = 0.0
    for i in range(x.shape[0]):
        s += x[i]*x[i]
    return np.sqrt(s)

@njit
def dot(x, y):
    s = 0.0
    for i in range(x.shape[0]):
        s += x[i]*y[i]
    return s

@njit
def arnoldi(indptr, indices, data, v0, m):
    n = v0.shape[0]
    V = np.zeros((n, m+1))
    H = np.zeros((m+1, m))
    y = np.empty(n)
    nrm = norm2(v0)
    for i in range(n):
        V[i, 0] = v0[i] / nrm
    for j in range(m):
        csr_matvec(indptr, indices, data, V[:, j], y)
        for i in range(j+1):
            h = dot(V[:, i], y)
            H[i, j] = h
            for t in range(n):
                y[t] -= h * V[t, i]
        for i in range(j+1):
            h = dot(V[:, i], y)
            H[i, j] += h
            for t in range(n):
                y[t] -= h * V[t, i]
        beta = norm2(y)
        H[j+1, j] = beta
        if beta < 1e-14:
            break
        invb = 1.0 / beta
        for t in range(n):
            V[t, j+1] = y[t] * invb
    return H[:m, :m].copy(), V[:, :m].copy()

def solve_arnoldi(A, k=5, ncv=40, v0=None):
    A = A.tocsr()
    indptr = A.indptr.astype(np.int32)
    indices = A.indices.astype(np.int32)
    data = np.ascontiguousarray(A.data, dtype=np.float64)
    n = A.shape[0]
    if v0 is None:
        v0 = np.ones(n, dtype=np.float64)
    else:
        v0 = np.asarray(v0, dtype=np.float64).copy()
    H, V = arnoldi(indptr, indices, data, v0, ncv)
    evals, evecs = np.linalg.eig(H)
    order = np.argsort(-np.abs(evals))[:k]
    evals = evals[order]
    vecs = V @ evecs[:, order]
    vecs = vecs / np.linalg.norm(vecs, axis=0)
    return evals, vecs

