def bench(name, fn, repeats=1):
    # warmup
    fn(problems[0])
    ts=0; oks=0
    for p in problems:
        for _ in range(repeats):
            t0=time.perf_counter()
            sol=fn(p)
            ts += time.perf_counter()-t0
        oks += task.is_solution(p, sol)
    print(f"{name}: {ts:.3f}s oks {oks}/{len(problems)}")
    return ts

def ref(p):
    return task.solve(p)

def which_lm(p):
    A=p["matrix"]; N=A.shape[0]; k=p["k"]
    v0=np.ones(N, dtype=A.dtype)
    vals, vecs = eigs(A, k=k, v0=v0, maxiter=N*200, ncv=20, which='LM', tol=0)
    pairs=sorted(zip(vals, vecs.T), key=lambda x: -abs(x[0]))
    return [x[1] for x in pairs]

def aslin(p):
    A=p["matrix"]; N=A.shape[0]; k=p["k"]
    v0=np.ones(N, dtype=A.dtype)
    vals, vecs = eigs(aslinearoperator(A), k=k, v0=v0, maxiter=N*200, ncv=20, tol=0)
    pairs=sorted(zip(vals, vecs.T), key=lambda x: -abs(x[0]))
    return [x[1] for x in pairs]

def which_and_aslin(p):
    A=p["matrix"]; N=A.shape[0]; k=p["k"]
